package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.availableLocaleSet()
 */
public class LocaleUtils_availableLocaleSet_TriageGen1Test {

    /**
     * Uses reflection to reset the private static field cAvailableLocaleSet to null.
     * This is necessary because the method uses a singleton/caching pattern,
     * and we need to test both the null case and the initialized case.
     */
    private void resetCache() throws Exception {
        Field field = LocaleUtils.class.getDeclaredField("cAvailableLocaleSet");
        field.setAccessible(true);
        field.set(null, null);
    }

    @Test
    public void testAvailableLocaleSet_InitialCall() throws Exception {
        // Ensure cache is null to trigger the 'if (set == null)' branch
        resetCache();

        Set result = LocaleUtils.availableLocaleSet();

        assertNotNull("The returned set should not be null", result);

        // Verify the set contains expected elements from availableLocaleList()
        for (Locale locale : LocaleUtils.availableLocaleList()) {
            assertTrue("The set should contain " + locale, result.contains(locale));
        }

        assertEquals("The size should match the available locale list", 
                     LocaleUtils.availableLocaleList().size(), result.size());
    }

    @Test
    public void testAvailableLocaleSet_SubsequentCallsReturnSameInstance() throws Exception {
        // First call to initialize
        resetCache();
        Set firstCall = LocaleUtils.availableLocaleSet();

        // Second call should return the same cached instance
        Set secondCall = LocaleUtils.availableLocaleSet();

        assertSame("Subsequent calls must return the exact same instance (cached)", firstCall, secondCall);
    }

    @Test
    public void testAvailableLocaleSet_IsUnmodifiable() throws Exception {
        resetCache();
        Set set = LocaleUtils.availableLocaleSet();

        // Attempting to modify the set should throw UnsupportedOperationException
        try {
            set.add(new Locale("test"));
            fail("Expected UnsupportedOperationException because the set is unmodifiable");
        } catch (UnsupportedOperationException e) {
            // Success
        }
    }

    @Test
    public void testAvailableLocaleSet_ConsistencyWithList() throws Exception {
        resetCache();
        Set set = LocaleUtils.availableLocaleSet();

        // Verify that the set correctly reflects the list provided by availableLocaleList
        for (Locale locale : LocaleUtils.availableLocaleList()) {
            assertTrue(set.contains(locale));
        }
    }
}
